-- Generated by Loom
-- Generator: hub
-- Hash function: SHA256
{{ config(materialized='incremental', incremental_strategy='append') }}
SELECT DISTINCT
    lower(hex(SHA256(upper(trim(cast(customer_id as String)))))) AS customer_hk,
    upper(trim(cast(customer_id as String))) AS customer_id,
    'orders_system' AS __record_source,
    now() AS __loaded_at
FROM {{ ref('stg_customers') }}
WHERE customer_id IS NOT NULL
{% if is_incremental() %}
  AND lower(hex(SHA256(upper(trim(cast(customer_id as String)))))) NOT IN (
    SELECT target.customer_hk FROM {{ this }} AS target
  )
{% endif %}
